def feat(x, k):
    from itertools import combinations_with_replacement
    return np.column_stack([np.prod(x[:, i], axis=1) for i in combinations_with_replacement(range(x.shape[1]), k)])

def gram(x):
    x = norm(x)
    return x @ x.T / x.shape[1]

def poly(x, d):
    from itertools import combinations_with_replacement
    return np.column_stack([np.ones(len(x))] + [np.prod(x[:, ids], axis=1) for k in range(1, d + 1) for ids in combinations_with_replacement(range(x.shape[1]), k)])

def calibrate(a, z, design, p0, bounds=(-np.inf, np.inf)):
    from scipy.optimize import least_squares

    def res(p):
        F = design(a, p)
        return (F @ fit(F, z) - z).ravel()
    r = least_squares(res, p0, bounds=bounds, gtol=1e-12, ftol=1e-12, xtol=1e-12, max_nfev=400)
    F = design(a, r.x)
    e = res(r.x).reshape(z.shape)
    loo = np.sqrt(np.mean((e / (1 - np.diag(F @ np.linalg.pinv(F)))[:, None]) ** 2))
    print('cal', r.x, 'rms', np.std(e), 'loo', loo)
    return (loo, lambda x: design(x, r.x) @ fit(F, z))
